   check_collapse SKIPS a multi-active target whose child key is unresolved, so its
   silence on this satellite is NOT a clean bill. Legacy collapse totals are
   NOT_MEASURABLE, never zero.
*/

with feeders as (
    select
        md5(upper('HUB_FINANCIAL_TRANSACTION|' || (HUB_FINANCIAL_TRANSACTION_BK__PTRANSACTION_ID))) as HUB_FINANCIAL_TRANSACTION_HK
        , INSTR_NUMBER as INSTRUMENT_REFERENCE
        , INSTR_DATE as INSTRUMENT_DATE
        , INSTRUMENT_AMT as INSTRUMENT_AMOUNT
        , 'BJAZ_HEALTH_WEBSERVICE_INFO' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_health_webservice_info') }}
    where (nullif(trim(PTRANSACTION_ID),'')) is not null
),

resolved as (
    select
        HUB_FINANCIAL_TRANSACTION_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then INSTRUMENT_REFERENCE end) as INSTRUMENT_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then INSTRUMENT_DATE end) as INSTRUMENT_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then INSTRUMENT_AMOUNT end) as INSTRUMENT_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_FINANCIAL_TRANSACTION_HK
),

hashed as (
    select
        *,
        case when INSTRUMENT_REFERENCE is not null or INSTRUMENT_DATE is not null or INSTRUMENT_AMOUNT is not null
                     then md5(upper(coalesce(cast(INSTRUMENT_REFERENCE as varchar), '') || '|' || coalesce(cast(INSTRUMENT_DATE as varchar), '') || '|' || coalesce(cast(INSTRUMENT_AMOUNT as varchar), '')))
                end as SAT_FINTXN_RECON_INSTRUMENT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_FINANCIAL_TRANSACTION_HK is not null
  and SAT_FINTXN_RECON_INSTRUMENT_HASHDIFF is not null
